const townDictionary=[...new Map([...TownTranslations,...Object.entries(InterfaceEnglish)])].sort((a,b)=>b[0].length-a[0].length);
const translatedCourses=new Set();
function registerCourseLanguage(){const c=currentCourse();if(!c||translatedCourses.has(c.id))return;translatedCourses.add(c.id);function add(base,en){if(typeof base==='string'&&typeof en==='string'&&base&&en&&base!==en)townDictionary.push([base,en]);else if(Array.isArray(base)&&Array.isArray(en))base.forEach((v,i)=>add(v,en[i]));else if(base&&en&&typeof base==='object'&&typeof en==='object')for(const key of ['q','a','wrong','answers','steps','pairs','left','right','blank','context','title','body','example','quote','category'])if(key in base)add(base[key],en[key]);}for(const ch of c.chapters){add(ch.title,ch.english);for(const sec of ch.sections){add(sec.title,sec.english);for(const l of sec.lessons)add(l,l.en);for(const q of sec.questions||[])add(q,q.en);}}townDictionary.sort((a,b)=>b[0].length-a[0].length);}
function translateTownText(text){let s=text;for(const[from,to]of townDictionary)if(from&&s.includes(from)){if(from.length===1){if(s.trim()===from)s=s.replace(from,to);}else s=s.split(from).join(to);}return s.replace(/第\s*(\d+(?:\/\d+)?)\s*章/g,'Chapter $1').replace(/(\d+)\s*个小节/g,'$1 sections').replace(/任务\s*(\d+)/g,'Task $1').replace(/整理背包中\s*(\d+)\s*份/g,'File $1 collected items').replace(/为「([^」]+)」/g,'For $1, ').replace(/[「」]/g,'').replace(/；/g,'; ').replace(/：/g,': ').replace(/查看(?=[A-Za-z])/g,'Inspect ').replace(/打开(?=[A-Za-z])/g,'Open ').replace(/与(?=[A-Za-z])/g,'Talk to ').replace(/([A-Za-z])与/g,'$1 and ').replace(/对话，/g,': ');}
function applyTownLanguage(){registerCourseLanguage();if(!document.createTreeWalker)return;document.documentElement.lang=state.language==='en'?'en':'zh-CN';const english=state.language==='en',walker=document.createTreeWalker(document.body,4);let node;while(node=walker.nextNode()){if(['SCRIPT','STYLE','TEXTAREA'].includes(node.parentElement?.tagName)||node.parentElement?.closest('[contenteditable],input'))continue;if(node._townTranslated===node.nodeValue){const next=english?node._townTranslated:node._townOriginal;if(node.nodeValue!==next)node.nodeValue=next;}else{node._townOriginal=node.nodeValue;node._townTranslated=translateTownText(node.nodeValue);if(english&&node.nodeValue!==node._townTranslated)node.nodeValue=node._townTranslated;}}
 document.querySelectorAll('[title], [aria-label], [placeholder]').forEach(el=>{for(const key of ['title','aria-label','placeholder','alt']){const v=el.getAttribute(key);if(v===null)continue;el._townAttrs??={};const old=el._townAttrs[key];if(!old||v!==old.en&&v!==old.zh)el._townAttrs[key]={zh:v,en:translateTownText(v)};el.setAttribute(key,el._townAttrs[key][english?'en':'zh']);}});
}
function changeTownLanguage(){state.language=state.language==='en'?'zh':'en';save();const away=activeAwayScene;close();if(away)openAwayScene(away);else{render();if(studyState()?.mode==='assessment'&&studyState().round)showChapterAssessment();}applyTownLanguage();}
$('languageToggle').onclick=changeTownLanguage;
const languageAway=openAwayScene;
openAwayScene=function(id,message=''){languageAway(id,message);if(!activeAwayScene)return;const el=document.createElement('button');el.id='awayLanguageToggle';el.textContent='中文 / EN';el.onclick=changeTownLanguage;($('awayScene').querySelector?.('.away-switches')||$('awayScene')).appendChild(el);applyTownLanguage();};
if(typeof MutationObserver!=='undefined'){let pending=false;new MutationObserver(()=>{if(pending)return;pending=true;queueMicrotask(()=>{pending=false;applyTownLanguage();});}).observe(document.body,{childList:true,subtree:true,characterData:true});}
const chineseGameGuide=showGameGuide;
showGameGuide=function(first=false,page='overview'){if(state.language!=='en'){chineseGameGuide(first,page);return;}const pages={overview:['Welcome to Knowledge Town','Choose any of six independent chapters. The first four teach the course; the coast and winter chapters are standalone adventures.',['Choose a chapter from the chapter map. Each chapter saves its own progress.','Find knowledge objects, read their definitions and collect them. Some objects need parts from the scene.','File the knowledge in its section device, then match concepts to definitions.','Submit a chapter’s foundations to unlock practice, review and mistakes. Score at least 90% in its assessment to complete it.']],study:['Learn, collect, think','You learn before you are assessed. Within a chapter, sections follow a learning sequence.',['Open a seed or object to read a definition and example. Readable objects can be collected immediately.','For assembly objects, return to the scene to find their parts. Read each part and fit it into the appropriate slot.','Place collected knowledge into the section device. When it is complete, drag concepts onto definitions or select one of each. Incorrect pairs can be retried.','Keep the completed device, continue the next section and submit the full chapter. Your knowledge chest stays available during practice.']],seaside:['Letters on the coast','Repair the chimes, guide the lights and post your summer letter.',['Find three fragments and place them in the sea chime stand. Drag them, or select an item and click its destination.','Turn the three beacons to East, South and West, then check them.','Read the letter clue and select Shell, Wave and Seagull in order.','Explore the bottle and tide pool for keepsakes. Use Restart chapter to play again.']],winter:['A snowlight delivery','Deliver the gifts, light the street and play the bells.',['Match gift ribbons to their destinations: bakery, station and Christmas tree.','The three switches toggle connected lamps. Make all three lamps shine, then check.','Read the score and ring Star, Bell and Moon in order.','Explore the train junction and snowman wardrobe. Restart this chapter whenever you want another playthrough.']]};const p=pages[page]||pages.overview;modal(`<span class="eyebrow">${first?'Your first map':'Travel guide'}</span><h2 id="dialogTitle">${p[0]}</h2><p>${p[1]}</p><div class="guide-tabs">${[['overview','Start here'],['study','Learning chapters'],['seaside','Coast'],['winter','Winter']].map(([k,name])=>`<button data-guide-page="${k}">${name}</button>`).join('')}</div><div class="guide-step-grid">${p[2].map((body,i)=>`<div><span class="guide-step-number">${i+1}</span><p>${body}</p></div>`).join('')}</div><p>Your progress is saved in this browser. Switching language preserves your progress. The three classic games are available through Other adventures.</p><div class="actions"><button id="guideChoose">Choose a chapter</button><button id="guideStudy" class="primary">Guide me through learning</button><button id="guideBeach">Explore the coast</button><button id="guideDismiss">Continue exploring</button></div>`,true);document.querySelectorAll('[data-guide-page]').forEach(el=>el.onclick=()=>showGameGuide(first,el.dataset.guidePage));$('guideChoose').onclick=()=>{finishWelcome();if(activeAwayScene)closeAwayScene();showChapterMap();};$('guideStudy').onclick=()=>{finishWelcome();if(activeAwayScene)closeAwayScene();if(currentCourse())beginStudyWalk();else close();};$('guideBeach').onclick=()=>{finishWelcome();openAwayScene('seaside');};$('guideDismiss').onclick=()=>{finishWelcome();close();};};
applyTownLanguage();
